INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369379, 15045, 'France 24', 'en', 'War in Ukraine: several wounded in drone attack on Moscow region', 'https://www.france24.com/en/europe/20260818-war-in-ukraine-several-people-wounded-in-drone-attack-on-moscow-region', 'A total of 620 drones targeted the Moscow region overnight, Russian officials said Monday, with several people wounded as buildings were struck. Moscow''s mayor said that air defence units intercepted more than 180 of the drones over the capital region.', 'https://s.france24.com/media/display/f1199f8a-9ac9-11f1-a53e-005056bfb2b6/w:1024/p:16x9/2026-08-16T090757Z-971134754-RC2KZMA4ADZ2-RTRMADP-3-UKRAINE-CRISIS-RUSSIA-WILDBERRIES-MOSCOW.jpg', '2026-08-18T06:32:32+00:00', '2026-08-18T06:41:40.921641'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
