INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (355606, 15076, 'Mint', 'en', 'Nikkei, KOSPI to US stocks: Global equity heatmap you must know before the opening bell of the Indian stock market', 'https://www.livemint.com/market/stock-market-news/nikkei-225-kospi-us-stocks-global-markets-equity-heatmap-stock-market-holidays-indian-stock-markets-opening-bell-11786933461146.html', 'Global markets today: The US stock market closed lower on Friday, even after the S&amp;P 500 briefly touched a fresh record high earlier in the session', 'https://www.livemint.com/lm-img/img/2026/08/17/1600x900/logo/Market_-_stocks_1545996587096_1786938030492_5cab683b-ac56-457e-800f-092c4472799c.jpg', '2026-08-17T03:37:29+00:00', '2026-08-17T04:34:25.288867'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (355654, 15076, 'Amar Ujala', 'hi', 'The Bonus Market Update: बाजार में गिरावट जारी; सेंसेक्स 300 से अधिक अंक टूटा, निफ्टी 24300 के नीचे', 'https://www.amarujala.com/business/bazaar/sensex-opening-bell-share-market-opening-sensex-nifty-share-market-news-and-updates-2026-08-17', 'भारतीय शेयर बाजार में सोमवार, 17 अगस्त को गिरावट के साथ कारोबार शुरू हुआ। सेंसेक्स 300 से अधिक अंक टूटा, जबकि निफ्टी 24,300 के नीचे आ गया। बजाज फिनसर्व और एचयूएल शीर्ष नुकसान वाले शेयरों में रहे।', '', '2026-08-17T04:16:16+00:00', '2026-08-17T04:34:59.016550'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
