INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (355944, 15076, 'The Economic Times', 'en', 'Sensex falls over 300 pts, Nifty below 24,300 as oil hits $90; IT, PSU stocks lead the slide', 'https://economictimes.indiatimes.com/markets/stocks/news/sensex-falls-over-300-pts-nifty-below-24300-as-oil-hits-90-it-psu-stocks-lead-the-slide/articleshow/133286171.cms', 'In a troubling trend, Nifty and Sensex slipped for a fifth day on Monday, as escalating oil prices and struggling IT stocks soured investor confidence. The broader market followed suit, opening lower and reflecting the ongoing negative sentiment. Analysts predict a stagnant market until new, favorable catalysts surface, prompting investors to keep a close eye on global trends and economic data that could sway the market''s direction.', 'https://img.etimg.com/photo/msid-133286171,imgsize-96522.cms', '2026-08-17T04:04:53+00:00', '2026-08-17T04:37:44.716499'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (355945, 15076, 'The Economic Times', 'en', 'US Stock Market: Fed uncertainty, oil prices in focus as earnings sustain market optimism', 'https://economictimes.indiatimes.com/markets/us-stocks/wall-street-guide/us-stock-market-fed-uncertainty-oil-prices-in-focus-as-earnings-sustain-market-optimism/articleshow/133286178.cms', 'Investors enter the week focused on interest rates, inflation and geopolitical risks, while strong corporate earnings support equities. The Federal Reserve’s Jackson Hole symposium and AI infrastructure spending remain key market catalysts. Robust earnings, positive guidance and Big Tech investment could offset macroeconomic concerns, though higher oil prices remain a potential threat.', 'https://img.etimg.com/photo/msid-133286178,imgsize-418852.cms', '2026-08-17T04:02:36+00:00', '2026-08-17T04:37:44.743365'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
