INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368056, 15085, 'Navbharat Times', 'hi', 'Thalapathy Vijay In Assembly , सॉरी .. वन मंत्री पर लगा करुणानिधि के अपमान का आरोप , भरे सदन में थलपति विजय ने मांगी माफी , हो रही तारीफ - cm thalapathy vijay apologises in tamil nadu assembly after forest minister omits honorific karunanidhi', 'https://navbharattimes.indiatimes.com/state/tamil-nadu/chennai/cm-thalapathy-vijay-apologises-in-tamil-nadu-assembly-after-forest-minister-omits-honorific-karunanidhi/articleshow/133309188.cms', '', 'https://static.langimg.com/nbt/thumb/133309239/tamil-nadu-cm-thalapathy-vijay.jpg?imgsize=195290&resizemode=75', '20260818', '2026-08-18T04:59:07.319224'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368378, 15085, 'The Commune', 'en', '100+ Families Without Basic Amenities In Joseph Vijay’s Perumbur Constituency, Kodungaiyur Residents Gherao MLA Office', 'https://thecommunemag.com/100-families-without-basic-amenities-in-joseph-vijays-perumbur-constituency-kodungaiyur-residents-gherao-mla-office', 'More than 50 residents from Kodungaiyur on Monday. 17 August 2026, gheraoed the office of Perambur MLA and Tamil Nadu CM Joseph Vijay, demanding basic civic amenities in their locality. The residents, from Vedantham Murugappa Naicker Street, alleged that more than 100 families living in the area have been deprived of basic facilities such as […] The post 100+ Families Without Basic Amenities In Joseph Vijay’s Perumbur Constituency, Kodungaiyur Residents Gherao MLA Office appeared first on The Commune .', '', '2026-08-18T05:23:24+00:00', '2026-08-18T05:45:45.429928'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369246, 15085, 'The Commune', 'en', 'Joseph Vijay’s TVK Paying ₹75000 Per Reel To Promote Vijay In Hindi Speaking States', 'https://thecommunemag.com/joseph-vijays-tvk-paying-%e2%82%b975000-per-reel-to-promote-vijay-in-hindi-speaking-states', 'A growing number of Instagram Reels portraying Tamil Nadu Chief Minister and Tamilaga Vettri Kazhagam (TVK) chief Joseph Vijay as a national political leader are originating from and circulating across Hindi-speaking states, Andhra Pradesh and Kerala. A recent investigation by Instagram content creator Dinesh Kumar has alleged that at least some of this promotional content […] The post Joseph Vijay’s TVK Paying ₹75000 Per Reel To Promote Vijay In Hindi Speaking States appeared first on The Commune .', 'https://thecommunemag.com/wp-content/uploads/2026/08/influ2-1.jpg', '2026-08-18T06:29:28+00:00', '2026-08-18T06:40:32.780350'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
