INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370155, 15085, 'The Commune', 'en', 'Joseph Vijay Apologizes Twice For Saying ‘Karunanidhi’, But Stays Silent When Marie Wilson Insults Tamil', 'https://thecommunemag.com/joseph-vijay-apologizes-twice-for-saying-karunanidhi-but-stays-silent-when-marie-wilson-insults-tamil', 'After spending months projecting the DMK as the Tamilaga Vettri Kazhagam’s principal political adversary, Tamil Nadu Chief Minister C. Joseph Vijay has once again found himself apologising in the Assembly over a reference to former Chief Minister M. Karunanidhi. This time, the apology came after Forest Minister Ranjith Kumar referred to Karunanidhi by name during […] The post Joseph Vijay Apologizes Twice For Saying ‘Karunanidhi’, But Stays Silent When Marie Wilson Insults Tamil appeared first on The Commune .', '', '2026-08-18T07:24:32+00:00', '2026-08-18T07:27:59.423685'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370156, 15085, 'The Commune', 'en', 'TVK Govt Floats ₹5.54 Crore Tender For Joseph Vijay’s New Office While Work Is Underway, Uploads It Online Only After Questions Raised', 'https://thecommunemag.com/tvk-govt-floats-%e2%82%b95-54-crore-tender-for-joseph-vijays-new-office-while-work-is-underway-uploads-it-online-only-after-questions-raised', 'The TVK government’s promise of transparency in public tenders is facing questions over the ₹5.54 crore work being undertaken to set up Chief Minister C. Joseph Vijay’s new office on the 10th floor of Namakkal Kavignar Maligai in Chennai. According to a report in The Times of India, three tenders floated by the Public Works […] The post TVK Govt Floats ₹5.54 Crore Tender For Joseph Vijay’s New Office While Work Is Underway, Uploads It Online Only After Questions Raised appeared first on The Commune .', '', '2026-08-18T06:44:44+00:00', '2026-08-18T07:27:59.440440'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
